<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import * as api from '../../api/training'
import type {Model,ParentComparison,ComparisonChange,Metrics} from '../../api/training'
import RecordPagination from '../RecordPagination.vue'
import EvaluationCharts from './EvaluationCharts.vue'
const props=defineProps<{model:Model;datasetId:string;versionId:string;preparationId:string}>()
const emit=defineEmits<{selected:[comparison:ParentComparison];complete:[comparison:ParentComparison]}>()
const route=useRoute(),router=useRouter(),current=ref<ParentComparison>(),parent=ref<Model>(),error=ref(''),busy=ref(false),tab=ref('metrics')
const history=ref<ParentComparison[]>([]),historyPage=ref(1),historySize=ref(5),historyTotal=ref(0)
const changes=ref<ComparisonChange[]>([]),changePage=ref(1),changeSize=ref(10),changeTotal=ref(0),filter=ref('errors'),counts=ref({improved:0,regressed:0,changed:0})
let alive=true,ticket=0,historyTicket=0,changesTicket=0,timer:ReturnType<typeof setTimeout>|undefined,notified=''
const complete=computed(()=>current.value?.parentStatus==='COMPLETED'&&current.value.childStatus==='COMPLETED')
const running=computed(()=>current.value&&(!api.terminal(current.value.parentStatus)||!api.terminal(current.value.childStatus)))
const metricNames:Record<string,string>={accuracy:'准确率',precision:'精确率',recall:'召回率',f1:'F1',macro_f1:'Macro-F1',roc_auc:'ROC AUC'}
const metrics=computed(()=>Object.entries(metricNames).map(([key,label])=>{const a=current.value?.parentMetrics?.[key as keyof Metrics],b=current.value?.childMetrics?.[key as keyof Metrics];const left=typeof a==='number'?a:null,right=typeof b==='number'?b:null;return{label,parent:left,child:right,delta:left!==null&&right!==null?right-left:null}}))
const percent=(value:number|null)=>value===null?'—':(value*100).toFixed(2)+'%'
function stop(){if(timer)clearTimeout(timer);timer=undefined}
async function loadHistory(){const id=props.model.modelId,request=++historyTicket;try{const data=await api.parentComparisons(id,historyPage.value,historySize.value);if(alive&&id===props.model.modelId&&request===historyTicket){history.value=data.items;historyTotal.value=data.total}}catch(e){if(alive&&request===historyTicket)error.value=e instanceof Error?e.message:'对照历史读取失败'}}
async function loadChanges(){if(!complete.value||!current.value)return;const id=current.value.childRunId,request=++changesTicket;try{const result=await api.comparisonChanges(id,changePage.value,changeSize.value,filter.value);if(alive&&id===current.value?.childRunId&&request===changesTicket){changes.value=result.items;changeTotal.value=result.total;counts.value={improved:result.improved,regressed:result.regressed,changed:result.changed}}}catch(e){if(alive&&request===changesTicket)error.value=e instanceof Error?e.message:'错误变化读取失败'}}
async function poll(id:string,token:number){
  stop();try{const result=await api.parentComparison(id);if(!alive||token!==ticket)return;if(result.childModelId!==props.model.modelId)throw new Error('该对照记录不属于当前模型');current.value=result
    if(!api.terminal(result.parentStatus)||!api.terminal(result.childStatus))timer=setTimeout(()=>void poll(id,token),1500)
    else{await loadHistory();if(complete.value){await loadChanges();if(notified!==id){notified=id;emit('complete',result)}}}
  }catch(e){if(alive&&token===ticket)error.value=e instanceof Error?e.message:'对照任务读取失败'}
}
async function choose(value:ParentComparison,remember=true){if(value.childModelId!==props.model.modelId)return;const token=++ticket;stop();current.value=value;error.value='';changes.value=[];changePage.value=1;changeTotal.value=0;counts.value={improved:0,regressed:0,changed:0};if(remember){emit('selected',value);await router.replace({query:{...route.query,tab:'comparison',comparison:value.childRunId,evaluation:value.childRunId}})}await poll(value.childRunId,token)}
async function start(){if(busy.value||running.value||!props.preparationId)return;const id=props.model.modelId,token=ticket;busy.value=true;error.value='';try{const value=await api.compareParent(id,props.datasetId,props.versionId,props.preparationId);if(alive&&id===props.model.modelId&&token===ticket)await choose(value)}catch(e){if(alive&&id===props.model.modelId)error.value=e instanceof Error?e.message:'共同评价未开始'}finally{busy.value=false}}
async function initialize(){stop();const token=++ticket;current.value=undefined;parent.value=undefined;error.value='';changes.value=[];historyPage.value=1;notified='';try{const [model,data]=await Promise.all([api.model(props.model.parentModelId!),api.parentComparisons(props.model.modelId,1,historySize.value)]);if(!alive||token!==ticket)return;parent.value=model;history.value=data.items;historyTotal.value=data.total;const requested=String(route.query.comparison||'');if(requested){const value=await api.parentComparison(requested);if(!alive||token!==ticket)return;if(value.childModelId!==props.model.modelId)throw new Error('该对照记录不属于当前模型');await choose(value,false)}else{const value=data.items.find(r=>r.preparationId===props.preparationId);if(value)await choose(value,false)}}catch(e){if(alive&&token===ticket)error.value=e instanceof Error?e.message:'共同评价读取失败'}}
watch(()=>[props.model.modelId,props.datasetId,props.versionId,props.preparationId],()=>void initialize(),{immediate:true})
watch(()=>route.query.comparison,value=>{if(value&&value!==current.value?.childRunId)void initialize()})
watch(tab,value=>{if(value==='errors')void loadChanges()})
onBeforeUnmount(()=>{alive=false;ticket++;historyTicket++;changesTicket++;stop()})
</script>
<template>
  <section class="work-panel parent-comparison">
    <div class="work-heading"><div><h2>续训前后共同评价</h2><span class="muted">同一测试划分，比较父版本和当前版本</span></div><el-button type="primary" :loading="busy" :disabled="!preparationId||!!running" @click="start">共同测试父子版本</el-button></div>
    <p v-if="error" class="work-error" role="alert">{{error}}</p>
    <div class="comparison-versions"><div><span>父版本 v{{parent?.versionNumber||1}}</span><strong>{{parent?.name||'读取父版本'}}</strong><el-tag v-if="current" size="small">{{api.stateNames[current.parentStatus]||current.parentStatus}}</el-tag></div><div><span>当前版本 v{{model.versionNumber||1}}</span><strong>{{model.name}}</strong><el-tag v-if="current" size="small">{{api.stateNames[current.childStatus]||current.childStatus}}</el-tag></div></div>
    <template v-if="current"><p class="comparison-context">测试划分 {{current.preparationId.slice(0,8)}} · {{current.createdAt?new Date(current.createdAt).toLocaleString('zh-CN'):''}}<template v-if="complete"> · 双方各评价{{current.childMetrics?.rows}}条</template></p><p v-if="current.parentError||current.childError" class="work-error">{{current.parentError||current.childError}}</p>
      <el-tabs v-if="complete" v-model="tab"><el-tab-pane label="指标变化" name="metrics"/><el-tab-pane label="混淆矩阵" name="matrix"/><el-tab-pane label="错误变化" name="errors"/><el-tab-pane label="ROC与PR曲线" name="curves"/></el-tabs>
      <el-table v-if="complete&&tab==='metrics'" :data="metrics" size="small"><el-table-column prop="label" label="指标"/><el-table-column label="父版本"><template #default="{row}">{{percent(row.parent)}}</template></el-table-column><el-table-column label="当前版本"><template #default="{row}">{{percent(row.child)}}</template></el-table-column><el-table-column label="变化（百分点）"><template #default="{row}"><strong :class="row.delta>0?'improved':row.delta<0?'regressed':''">{{row.delta===null?'—':(row.delta>0?'+':'')+(row.delta*100).toFixed(2)}}</strong></template></el-table-column></el-table>
      <div v-if="complete&&['matrix','curves'].includes(tab)" class="comparison-charts"><section><h3>父版本</h3><EvaluationCharts :metrics="current.parentMetrics!" :view="tab==='matrix'?'matrix':'curves'" :show-metrics="false"/></section><section><h3>当前版本</h3><EvaluationCharts :metrics="current.childMetrics!" :view="tab==='matrix'?'matrix':'curves'" :show-metrics="false"/></section></div>
      <section v-if="complete&&tab==='errors'"><div class="comparison-errors-heading"><span>改正{{counts.improved}}条 · 新增错误{{counts.regressed}}条 · 判定变化{{counts.changed}}条</span><el-select v-model="filter" aria-label="错误变化类型" @change="changePage=1;loadChanges()"><el-option value="errors" label="任一版本判错"/><el-option value="improved" label="续训后改正"/><el-option value="regressed" label="续训后新增错误"/><el-option value="changed" label="判定发生变化"/></el-select></div><el-table :data="changes" size="small" empty-text="该筛选下没有样本"><el-table-column prop="sentence1" label="文本一" min-width="180"/><el-table-column prop="sentence2" label="文本二" min-width="180"/><el-table-column label="实际" width="75"><template #default="{row}">{{row.label===1?'复用':'非复用'}}</template></el-table-column><el-table-column label="父→子" width="110"><template #default="{row}">{{row.parentPrediction}} → {{row.childPrediction}}<small class="comparison-scores">{{row.parentScore.toFixed(3)}} → {{row.childScore.toFixed(3)}}</small></template></el-table-column></el-table><RecordPagination v-model:current-page="changePage" v-model:page-size="changeSize" :total="changeTotal" @change="loadChanges"/></section>
      <p v-if="running" aria-live="polite">正在依次评价两个版本，完成后自动展示对照结果。</p>
    </template><p v-else class="muted">选择测试划分后开始共同评价，原模型与权重保留。</p>
    <details class="comparison-history"><summary>共同评价记录 · {{historyTotal}}次</summary><el-table :data="history" size="small"><el-table-column label="时间" min-width="160"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="划分" min-width="110"><template #default="{row}">{{row.preparationId.slice(0,8)}}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}">父 {{api.stateNames[row.parentStatus]}} · 子 {{api.stateNames[row.childStatus]}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button size="small" @click="choose(row)">查看</el-button></template></el-table-column></el-table><RecordPagination v-model:current-page="historyPage" v-model:page-size="historySize" :total="historyTotal" @change="loadHistory"/></details>
  </section>
</template>
<style scoped>
.comparison-versions{display:grid;grid-template-columns:1fr 1fr;gap:12px}.comparison-versions>div{border:1px solid var(--line);padding:10px 12px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.comparison-versions span{font-size:11px;color:var(--muted)}.comparison-versions strong{font-size:13px}.comparison-context{font-size:11px;color:var(--muted);margin:10px 0}.comparison-charts{display:grid;grid-template-columns:1fr 1fr;gap:16px}.comparison-charts h3{font-size:14px}.comparison-charts :deep(.experiment-grid){grid-template-columns:1fr}.comparison-errors-heading{display:flex;justify-content:space-between;align-items:center;font-size:12px;margin-bottom:10px}.comparison-errors-heading .el-select{width:190px}.comparison-scores{display:block;color:var(--muted);font-size:10px}.comparison-history{margin-top:12px;border-top:1px solid var(--line);padding-top:10px}.comparison-history summary{cursor:pointer;font-size:12px;margin-bottom:8px}.improved{color:var(--el-color-success)}.regressed{color:var(--el-color-danger)}@media(max-width:800px){.comparison-versions,.comparison-charts{grid-template-columns:1fr}}
</style>
